------------ import ------------
local Decorator = import("Frame.AI.BT.Decorators.Decorator")
------------ import ------------

------------ define ------------
local TaskStatus = Decorator.TaskStatus
------------ define ------------

---@class ConditionalDecorator
local ConditionalDecorator = Class("ConditionalDecorator", Decorator)

function ConditionalDecorator:__init(child, conditional, shouldReevaluate)
    Decorator.__init(self, child)
    self.discriminator = "IConditional"
    
    self._conditional = conditional
    self._shouldReevaluate = shouldReevaluate
    
    self._conditionalStatus = TaskStatus.Invalid
end

function ConditionalDecorator:Invalidate()
    Decorator.Invalidate(self)
    self._conditionalStatus = TaskStatus.Invalid

end

function ConditionalDecorator:Update(context)
    assert(self._child ~= nil, "child 不能为空")

    self._conditionalStatus = self._child:ExecuteConditional(context)
    if self._conditionalStatus == TaskStatus.Success then
        return self._child:Tick(context)
    end

    return TaskStatus.Failure
end

---ExecuteConditional
--- 在shouldReevaluate标志之后执行条件，或者用一个选项来强制更新。
--- 终止将强制更新，以确保他们在条件变化时得到适当的数据。
---@param context table
---@param forceUpdate table
function ConditionalDecorator:ExecuteConditional(context, forceUpdate)
    if forceUpdate == nil then
        forceUpdate = true
    end

    if forceUpdate or self._shouldReevaluate or self._conditionalStatus == TaskStatus.Invalid then
        self._conditionalStatus = self._conditional:Update(context)
    end
    
    return self._conditionalStatus
    
end

return ConditionalDecorator
 